from pathlib import Path
p=Path(__file__).parent
s=(p/'Ilha_Viva_Ecossistema_03.html').read_text()
start=s.index('<script>')+len('<script>');end=s.index('let state=Insects.create()',start)
s=s[:start]+'\n'+'\n'.join((p/f).read_text() for f in ['ecology.js','flora.js','insects.js','vertebrates.js'])+'\n'+s[end:]
# Replace calls in UI only, not inside the engines.
start=s.index('let state=Insects.create()');head,ui=s[:start],s[start:]
ui=ui.replace('Insects.create()','Vertebrates.create()').replace('Insects.tick(state)','Vertebrates.tick(state)').replace('ivEco032','ivEco033').replace('${fm.richness}/6','${fm.richness}/${Flora.species.length}').replace("let c=state.cells[sel];ctx.strokeStyle", "if($('showAnimals').checked){for(let a of state.animals){let t=state.cells[a.pos],x=t.x*k+6,y=t.y*k+6;ctx.fillStyle='#101b17';ctx.fillRect(x-4,y-4,8,8);ctx.fillStyle=Vertebrates.P[a.sp].color;ctx.fillRect(x-3,y-3,6,6);ctx.fillStyle='#1a2922';ctx.fillRect(x,y,2,2)}}let c=state.cells[sel];ctx.strokeStyle")
ui=ui.replace('let im=Insects.metrics(state)',"let am=Vertebrates.metrics(state),ae=state.animalEvents;$('animalStats').innerHTML=`<b>${am.total} vertebrados</b> · ${am.juveniles} juvenis<br>`+Vertebrates.P.map((p,i)=>`<div><i class='dot' style='background:${p.color}'></i>${p.name}: <b>${am.count[i]}</b> · nascimentos ${ae.births[i]} · mortes ${ae.deaths[i]}</div>`).join('')+`<hr>Fezes produzidas: ${num(ae.dung)} · dispersões por lêmures: ${ae.seedDeposits}<br>Predação: ${ae.predation[0]} insetos e ${ae.predation[1]} lêmures<br>Refeições de besouros: ${state.insectEvents.meals[2]}`;$('inspect').innerHTML+=`<hr>Vertebrados locais: ${state.animals.filter(a=>a.pos===sel).map(a=>Vertebrates.P[a.sp].name+' ('+a.state+')').join(', ')||'nenhum'}`;let im=Insects.metrics(state)")
ui=ui.replace("$('weather').value='auto';", "$('weather').value='auto';$('faunaMode').value='normal';").replace("$('weather').value=state.weather;", "$('weather').value=state.weather;$('faunaMode').value=state.faunaMode;").replace("$('showInsects').onchange=draw;", "$('showInsects').onchange=draw;$('showAnimals').onchange=draw;$('faunaMode').onchange=()=>state.faunaMode=$('faunaMode').value;")
s=head+ui
s=s.replace('Ecossistema 03 | Insetos','Ecossistema 04 | Teia ecológica').replace('seis plantas • quatro grupos de insetos','oito categorias vegetais • quatro grupos de insetos • quatro vertebrados').replace('Coortes vegetais e agentes de insetos; símbolos diagnósticos, não sprites finais.','Coortes vegetais e agentes animais; símbolos diagnósticos, não sprites finais.').replace('<label for="light">Luz</label>','<label for="faunaMode">Vertebrados</label><select id="faunaMode"><option value="normal">Todos presentes</option><option value="noFossa">Sem fossa</option><option value="none">Sem vertebrados</option></select><label for="light">Luz</label>').replace('<h2>Estado da bacia</h2>','<h2>Estado da bacia</h2><div id="animalStats" class="fine"></div><div class="row"><label><input type="checkbox" id="showAnimals" checked> Mostrar vertebrados</label></div><hr>')
(p/'Ilha_Viva_Ecossistema_04.html').write_text(s)
